package l1j.server.server.model; import java.util.*;import l1j.server.server.model.Instance.L1PcInstance;public class L1World {public static final L1World INSTANCE=new L1World();public final List<L1PcInstance> list=new ArrayList<>();public int borrowed,released,radius;public static L1World getInstance(){return INSTANCE;}public List<L1PcInstance> borrowVisiblePlayerFast(L1Object a){borrowed++;return list;}public void releaseVisiblePlayerFast(List<L1PcInstance> a){if(a!=list)throw new AssertionError();released++;}public List<L1PcInstance> getVisiblePlayer(L1Object a){return list;}public List<L1PcInstance> getVisiblePlayer(L1Object a,int r){radius=r;return list;}}
